    posMainTourScenarioTitle: 'POS 홈 데모',
    posMainTourH1Title: 'POS 홈(데모)',
    posMainTourH1Body:
      '이 투어는 첫 화면의 주요 진입(홀·포장·배달·관리)이 어디인지 짚어 줍니다. POS는 반드시 **본인 이름 계정으로 로그인**해 사용하고, 교대/퇴근 시에는 로그아웃하세요. 데모일 때 쓰기/결제는 운영 서버에 남지 않을 수 있습니다.',
